SELECT cp.cp_department, d.d_year, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_return_quantity FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk WHERE cp.cp_type = 'quarterly' AND d.d_year = 1920 GROUP BY cp.cp_department, d.d_year
